  LanguageConfig_2ndAnniversarySenderText_CN = {Text = "Ramona"},
  LanguageConfig_2ndAnniversaryText_CN = {
    Text = "Bất kể bạn đang ở đâu, %player%.\nMythag luôn cố gắng thực hiện liên kết chiều không gian, có lẽ chúng ta sẽ sớm gặp lại nhau.\nBúp bê nói rằng cô ấy đã định vị được chiều không gian của bạn, tôi không thể mô tả nó khiến trái tim tôi cảm thấy như thế nào.\nDù tôi thích những thứ rõ ràng, chính xác và có quy tắc rõ ràng, nhưng chỉ trong trường hợp này, bất kỳ hy vọng nào, dù rất nhỏ và gần như không thực tế, cũng không sao cả.\nThay vì chờ đợi lâu dài, tôi càng không thể tưởng tượng sự chia ly mà không bao giờ gặp lại.\nNếu lần này không thành công, không sao, lần sau, lần nữa, hoặc hàng nghìn lần, bất kể bao nhiêu lần cần thiết, tất cả chúng tôi ở Mythag nhất định sẽ đưa bạn trở lại.\nDù hiện tại chúng ta đang ở hai chiều không gian, Mythag vẫn tìm cách thu thập công nghệ bạc để mang lại sự hỗ trợ cho bạn, hãy tập hợp những ký ức quá khứ của chúng ta, tạo ra những ký ức mới, để những món quà này mang lại sự giúp đỡ cho bạn.\nChúng ta đều biết, bạn chắc chắn sẽ trở lại.\nBởi vì tôi rất giỏi chờ đợi."
