  LanguageConfig_AlchemyDecomposeTrinketRuleContent_CN = {
    Text = "1, Người giữ gìn có thể thực hiện phân rã giao ước tại đây, sau khi phân rã sẽ không thể phục hồi, xin hãy lựa chọn cẩn thận.\n2, Nếu giao ước trong bánh xe định mệnh được chọn để phân rã có bao gồm giao ước đã được tăng cường, người giữ gìn phải hoàn thành việc trả lời câu hỏi trước khi có thể phân rã.\n3, Giao ước đang sử dụng trong bất kỳ \"Đội hình\" hoặc \"Kế hoạch giao ước\" hoặc \"Người đánh thức trợ chiến\" không thể phân rã."
