  LanguageConfig_AssistanceSystemIntroduction_CN = {
    Text = "·Người giữ bí mật có thể chọn 1 thể thức tỉnh để hỗ trợ chiến đấu, các Người Giữ Gìn đã theo dõi lẫn nhau có thể sử dụng thể thức tỉnh hỗ trợ của bạn trong Phế tích Dung Thực, Bản ghi cấm và Giấc mơ thám hiểm. \n·Mỗi khi các Người Giữ Gìn khác sử dụng thể thức tỉnh hỗ trợ của bạn để điều tra thành công, bạn có thể nhận được phần thưởng \"Vé hoa hồng vàng\" ×1000, mỗi ngày tối đa nhận được 20 lần thưởng. \n·Khi phần thưởng Vé hoa hồng vàng tích lũy đến 50 lần, Người Giữ Gìn cần phải nhận thưởng trước khi có thể tiếp tục nhận phần thưởng hỗ trợ."
