  LanguageConfig_AwakerAssistRuleTitle_CN = {
    Text = "Quy tắc hỗ trợ"
  },
  LanguageConfig_AwakerAssistRule_CN = {
    Text = "·Khi tham gia các chế độ như Rỗng rỗng, Cấm kỵ soạn lục, Giấc mơ thám hiểm, Siêu nghiệm tồn tại, bạn có thể chọn sử dụng 1 thân thể được đánh thức mà Người Giữ Gìn đã theo dõi để tham chiến. \n·Thân thể được đánh thức hỗ trợ cần đáp ứng giới hạn giới vực của biên đội hiện tại. Nếu không phù hợp, thân thể được đánh thức hỗ trợ sẽ không thể ra trận. Người giữ bí mật có thể trở về điều chỉnh biên đội, sau đó tiếp tục tham gia. \n·Một số hoạt động có thể có quy tắc hỗ trợ đặc biệt bổ sung. Vui lòng xem \"Lời giải thích hoạt động\" của hoạt động đó để hiểu rõ hơn."
