  LanguageConfig_AwakerFavorImproveResonance_CN = {
    Text = "Cảm ứng phụ gia"
  },
  LanguageConfig_AwakerFavorability_Description_Detail_CN = {
    Text = "<Title:[Cách nhận tỷ lệ đồng điều]>\n·Sau khi hoàn thành các màn chơi như điều tra hành động, Bản ghi đặc nhiệm, duy thức tiềm hành và Giấc mơ thám hiểm, Thể thức tỉnh tham chiến có thể nhận được tỷ lệ đồng điều.\n·Thể thức tỉnh chơi càng nhiều bài, tiêu thụ Điểm tính toán và điên cuồng càng nhiều thì nhận được tỷ lệ đồng điều càng nhiều; cấp độ đề xuất của màn chơi càng cao thì tỷ lệ đồng điều nhận được cũng càng nhiều.\n·Năng lượng chìa khóa bạc của người giữ bí mật tiêu thụ càng nhiều, Thể thức tỉnh tham chiến nhận được tỷ lệ đồng điều cũng càng nhiều.\n·Tỷ lệ đồng điều nhận được trong thời gian chiến đấu thủ công gấp 3 lần so với khi bật \"Chiến đấu tự động\".\n·Sau khi dùng Trợ Chiến hoàn thành màn chơi, tỷ lệ đồng điều nhận được của Thể thức tỉnh tham chiến của người giữ bí mật tăng 50%.\n·Sau khi mời Thể thức tỉnh vào ký túc xá, mỗi 5 phút có thể nhận được 1 điểm tỷ lệ đồng điều.\n·Sau khi lưu trữ ngoại tuyến vượt quá 300 điểm, tốc độ nhận giảm xuống còn 1 điểm mỗi 15 phút, tối đa có thể lưu trữ đến 3000 điểm.\n\n<Title:[Cấp độ tỷ lệ đồng điều]>\n·Thu thập tỷ lệ đồng điều của Thể thức tỉnh có thể nâng cấp độ tỷ lệ đồng điều, cấp độ càng cao có thể mở khóa thêm nhiều giọng nói và câu chuyện của Thể thức tỉnh, một số cấp độ còn có thể nhận được \"Hạt Nhân Sạch Will\".\n·Sau khi tỷ lệ đồng điều của Thể thức tỉnh đạt Lv15, có thể thông qua \"Đồng Tâm Như Ý\" tiêu thụ \"Biểu Tượng Thành Tâm\" để nâng giới hạn cấp độ lên từng bậc đến Lv20, mỗi cấp có thể nhận được \"Phân mảnh linh hạch tinh túy\" ×5, khi nâng lên Lv20 còn có thể nhận thêm \"Bạc Ảnh\".\n·Sau khi tỷ lệ đồng điều của Thể thức tỉnh đạt giới hạn cấp độ hiện tại sẽ không tiếp tục tích lũy, cần hoàn thành Đồng Tâm Như Ý trước mới có thể tiếp tục nhận."
  },
