  LanguageConfig_BPNewOpenContent_CN = {
    Text = "Đã mở đề tài học kỳ mới!\nHoàn thành thử thách hàng ngày và thử thách hàng tuần của lớp học mật cảnh, nâng cấp bậc đề tài, nhận phần thưởng phong phú!"
