  LanguageConfig_BonusCardRateText_CN = {
    Text = "\"hạt giống phong thuần\" nhận được tăng cường tham vọng: <NetworkDelayGreen:{s1}>"
  },
  LanguageConfig_BonusCardTipsContent_CN = {
    Text = "1. Người giữ bí mật sở hữu thể đánh thức cụ thể hoặc vòng mệnh(không yêu cầu ra trận) có thể giúp phần thưởng nhiệm vụ của \"ham muốn hỗn loạn\" nhận thêm tỷ lệ rơi \"hạt giống phong thuần\"(bao gồm tái hiện), chi tiết như sau:\n· Thân thể được đánh thức \"Thái Di Sơ\":Khởi linh 0/1/2/3 trở lên, tăng 20%/30%/40%/50%\n· Vòng mệnh SSR \"Sự nuôi dưỡng từ bi\":Độ chồng 0/1/2/3 trở lên, tăng 20%/30%/40%/50%\n· Vòng mệnh SR \"Nụ hôn cháy bỏng\":Độ chồng 0/1/2/3 trở lên, tăng 20%/30%/40%/50%\n2. Tỷ lệ tăng cường \"ham muốn\" của các thân thể đánh thức hoặc vòng mệnh khác nhau sẽ được tính theo cách cộng dồn."
  },
  LanguageConfig_BonusCardTipsTitle_CN = {
    Text = "Giải thích về tăng cường Tham Lam"
  },
  LanguageConfig_BonusRuleContent_A24Activity_CN = {
    Text = "1, Người giữ bí mật sở hữu thân thể được đánh thức cụ thể hoặc vòng mệnh(không yêu cầu ra trận) có thể giúp phần thưởng nhiệm vụ của \"mã hóa ký ức\" nhận được thêm tỷ lệ rơi \"mảnh ghép ký ức\"(bao gồm tái hiện), chi tiết như sau:\n·Thân thể được đánh thức \"24\":Khởi linh 0/1/2/3 trở lên, tăng 20%/30%/40%/50%\n·Vòng mệnh SSR \"Hồi Phệ Dị Thể\":Tầng 0/1/2/3 trở lên, tăng 20%/30%/40%/50%\n·Vòng mệnh SR \"Quyết Tâm Cá Tuyết Bạc\":Tầng 0/1/2/3 trở lên, tăng 20%/30%/40%/50%\n2, Hiệu ứng \"tăng cường lý tính\" của các thân thể được đánh thức hoặc vòng mệnh khác nhau sẽ được cộng dồn."
  },
  LanguageConfig_BonusRuleContent_ArachneActivity_CN = {
    Text = "1. Thủ Mật Nhân sở hữu Giác Tỉnh Thể hoặc Mệnh Luân cụ thể(không yêu cầu ra trận) có thể giúp \"Cuống Vé Ghế Nhung\" trong phần thưởng nhiệm vụ màn chơi \"Sân Khấu Của Rối\" nhận được thêm bonus rơi đồ, chi tiết bonus như sau:\n·Giác Tỉnh Thể\"Arachne\": Khải Linh 0/1/2/3 trở lên, bonus 20%/30%/40%/50%.\n·Mệnh Luân SSR \"Lưới Dệt Vĩnh Thế\": Điệp Vị 0/1/2/3 trở lên, bonus 20%/30%/40%/50%.\n·Mệnh Luân SR \"Bánh Xe Tơ Định Mệnh\": Điệp Vị 0/1/2/3 trở lên, bonus 20%/30%/40%/50%.\n2.\"Bonus Hoạt Động\" của các Giác Tỉnh Thể hoặc Mệnh Luân khác nhau được tính theo phương thức cộng dồn."
