  LanguageConfig_DailyChallengeInstructionsExample_CN = {
    Text = "({s1}) \"{s2}\": {s3}"
  },
  LanguageConfig_DailyChallengeInstructionsV2_CN = {
    Text = "<Title:[Giấc mơ thám hiểm]>\n·Di vật ban đầu, di vật màn chơi sẽ thay đổi vào lúc 9 giờ sáng Thứ Hai hàng tuần (GMT+8).\n·Mỗi lần thử thách sẽ ngẫu nhiên vào một cảnh thử thách.\n<Title:[Kinh nghiệm Lặn sâu]>\n·Nếu \"Cấp độ Người Giữ Gìn\" gần với cấp độ đề xuất của màn chơi, thì chiến thắng thử thách sẽ hoàn thành thành tựu lặn sâu và nhận được \"Kinh nghiệm lặn sâu\".\n   ·\"Hành Trình Thử Thách\": Khi \"Cấp độ đề xuất\" của độ khó thử thách cao hơn \"Cấp độ Người Giữ Gìn\" - 40 cấp, có thể nhận được kinh nghiệm lặn sâu cơ bản.\n   ·\"Hành Trình Vượt Giới\": Khi \"Cấp độ đề xuất\" của độ khó thử thách cao hơn \"Cấp độ Người Giữ Gìn\" - 20 cấp, có thể nhận thêm một phần kinh nghiệm lặn sâu cơ bản.\n<Title:[Cấp độ Lặn sâu]>\n·Khi kinh nghiệm lặn sâu đạt đến một giá trị nhất định, cấp độ lặn sâu tăng lên. Mỗi lần lên cấp đều có thể nhận được phần thưởng phong phú.\n<Title:[Cập nhật Mùa Giải]>\n·Thông thường, mùa giải đặt lại sau mỗi 28 ngày.\n·Khi kết thúc điều tra sẽ nhận được điểm điều tra, mỗi mùa giải sẽ ghi lại điểm điều tra cao nhất trong mùa để xếp hạng, có thể điều tra lại để nâng cao điểm. Khi điểm điều tra bằng với Người Giữ Gìn khác, sẽ được xem là cùng thứ hạng.\n·Khi kết thúc mùa giải sẽ tính toán xếp hạng mùa giải và gửi phần thưởng xếp hạng qua thư. Người giữ bí mật có thể xem phần thưởng xếp hạng bằng cách nhấp vào \"Bảng xếp hạng\" - \"Phần thưởng xếp hạng\".\n·Mỗi mùa giải đều có Nhiệm Vụ Mùa Giải, hoàn thành Nhiệm Vụ Mùa Giải có thể nhận được phần thưởng phong phú. Nhiệm Vụ Mùa Giải sẽ đặt lại khi kết thúc mùa giải.\n<Title:[Tăng cường Thể thức tỉnh mỗi mùa giải]>\n·Mỗi mùa giải, mỗi Cõi sẽ có hai Thể thức tỉnh ngẫu nhiên trở nên điên cuồng trong Hành động Giấc mơ thám hiểm của mùa giải này, do đó Thể chất, Tấn công, Phòng thủ của chúng tăng 50%.\n<Title:[Điểm Điều Tra]>\n·Khi kết thúc điều tra sẽ tính toán dựa trên điểm cơ bản độ khó của màn chơi hiện tại và các hạng mục điểm đã hoàn thành, độ khó càng cao thì điểm cơ bản độ khó càng cao.\n·Phía Dưới là các hạng mục điểm cụ thể.\n1. \"Đồng hồ cát thời gian\": Lượt ban đầu là 50, mỗi 1 lượt Còn Lại sẽ nhận thêm 20 điểm.\n2. \"Tiếng Gọi Vực Thẳm\": Khi xuất trận với 1 / 2 / 3 / 4 Thể thức tỉnh được tăng cường, nhận được 250 / 500 / 750 / 1000 điểm.\n3. \"Giải Cứu Ảo Cảnh\": Mỗi lần sử dụng 1 Thân thể Linh tri thức khẩn cấp, điểm điều tra giảm 20%, kích hoạt nhiều lần thì nhân nhiều lần.\n4. \"Tiên Phong Khai Mộng\": Lần đầu chơi trong ngày nhận được 500 điểm."
  },
  LanguageConfig_DailyChallengeInstructions_CN = {
    Text = "<Title:【Giấc mơ thám hiểm】>\n·Các di vật khởi đầu, di vật màn chơi sẽ thay đổi vào lúc 9 giờ sáng(GMT+8) vào Thứ Hai hàng tuần.\n·Mỗi lần thách thức sẽ ngẫu nhiên vào một cảnh thách thức.\n<Title:【Kinh nghiệm Lặn sâu】>\n·Nếu \"Cấp độ Người Giữ Gìn\" gần với cấp độ đề xuất của màn chơi, thì chiến thắng thách thức có thể hoàn thành thành tựu lặn sâu, nhận được \"Kinh nghiệm Lặn sâu\".\n   ·\"Hành trình thách thức\": Khi \"Cấp độ đề xuất\" của độ khó thách thức cao hơn \"Cấp độ Người Giữ Gìn\"- 40 cấp, có thể nhận được kinh nghiệm lặn sâu cơ bản.\n   ·\"Hành trình vượt qua\": Khi \"Cấp độ đề xuất\" của độ khó thách thức cao hơn \"Cấp độ Người Giữ Gìn\"- 20 cấp, có thể nhận thêm một phần kinh nghiệm lặn sâu cơ bản.\n<Title:【Cấp độ Lặn sâu】>\n·Khi kinh nghiệm lặn sâu đạt đến một giá trị nhất định, cấp độ lặn sâu tăng lên. Mỗi lần lên cấp đều có thể nhận được phần thưởng phong phú.\n<Title:【Cập nhật mùa giải】>\n·Trong trường hợp thông thường, mùa giải sẽ đặt lại sau mỗi 28 ngày.\n·Kết thúc điều tra sẽ nhận được điểm điều tra, mỗi mùa giải sẽ ghi lại điểm điều tra cao nhất trong mùa để làm bảng xếp hạng mùa giải, có thể điều tra lại để nâng cao điểm số. Khi điểm điều tra của Người Giữ Gìn khác giống nhau, sẽ coi là cùng một thứ hạng.\n·Khi kết thúc mùa giải sẽ tính toán xếp hạng mùa giải và gửi phần thưởng xếp hạng mùa giải qua thư. Người giữ bí mật có thể xem phần thưởng xếp hạng bằng cách nhấp vào \"Bảng xếp hạng\"-\"Phần thưởng xếp hạng\".\n·Mỗi mùa giải đều có Nhiệm Vụ Mùa Giải, hoàn thành Nhiệm Vụ Mùa Giải có thể nhận được phần thưởng phong phú. Nhiệm Vụ Mùa Giải sẽ được đặt lại khi kết thúc mùa giải.\n<Title:【Tăng cường Thể thức tỉnh mỗi mùa giải】>\n·Mỗi Cõi trong mỗi mùa giải sẽ có hai Thể thức tỉnh ngẫu nhiên trở nên cuồng loạn trong hành động Giấc mơ thám hiểm của mùa giải này, do đó Thể chất, Tấn công, Phòng thủ của chúng tăng 50%.\n<Title:【Điểm điều tra】>\n·Kết thúc điều tra sẽ dùng điểm cơ bản theo độ khó của màn chơi hiện tại cộng với các mục điểm đã hoàn thành để tính toán, độ khó càng cao thì điểm cơ bản càng cao.\n·Bên Dưới là các mục điểm cụ thể.\n1,\"Đồng hồ cát thời gian\": Số vòng khởi đầu là 50, mỗi vòng Còn Lại sẽ nhận thêm 20 điểm.\n2,\"Gọi vực thẳm\": Khi sử dụng 1/2 Thể thức tỉnh tăng cường ra trận, nhận được 250 / 500 điểm.\n3,\"Cứu hộ trong ảo ảnh\": Mỗi lần sử dụng 1 lần Thân thể Linh tri thức khẩn cấp, điểm điều tra giảm 20%, nhiều lần kích hoạt sẽ nhân nhiều lần.\n4,\"Người tiên phong mở mộng\": Lần đầu chơi trong ngày nhận được 500 điểm."
  },
