  LanguageConfig_DiamondDonateTipContent_CN = {
    Text = "<Title:Quy tắc quyên góp>\n·Tất cả nguồn lỏng tiêu thụ qua「quyên góp nguồn lỏng」sẽ được tính vào tổng giá trị quyên góp. \n·Ngoài ra, nguồn lỏng được quyên góp trực tiếp khi không đủ bạc tâm trong「hoán tỉnh」cũng sẽ được tính vào. \n<Title:Quy tắc thưởng>\n·Mỗi giọt nguồn lỏng quyên góp tương ứng nhận được 1 điểm đóng góp. \n·Mỗi khi điểm đóng góp đạt 2500 sẽ nhận được 1 phần thưởng đặc biệt. \n·Mỗi 20 phần thưởng là một chu kỳ. \n·Tổng số phần thưởng trong mỗi chu kỳ bao gồm:「Tinh túy nguyên thủy linh hạch」×1,「Nguyên thủy linh hạch」×3,「Đá hiền triết」×6,「Bút lông kỷ niệm」×800,「Phiếu quà của Vô Hình」×100,「Chấn ấn nghìn mặt」×5000,「Vé hoa hồng vàng」×50000000."
  },
