  LanguageConfig_PasswordBattleRuleTips_CN = {
    Text = "·Đối chiến mật mã: Sau khi tạo đối chiến, bạn có thể đăng <color=#5EF2FF>giá trị pha</color> trên mạng xã hội hoặc phần mềm nhắn tin để mời nhóm người tham gia, những Người Giữ Gìn khác có thể nhập <color=#5EF2FF>giá trị pha</color> để tham gia đối chiến của bạn. Vì chỉ có thể đối chiến với một người cùng lúc, nên suất đối chiến theo nguyên tắc ai đến trước được trước, sau khi đối chiến bắt đầu thành công, những Người Giữ Gìn khác được mời sẽ bị từ chối.\n·Từ chối đối chiến: Nếu gặp Người Giữ Gìn mà bạn không muốn đối chiến, người tạo cũng có thể từ chối đối chiến với họ. Từ chối quá nhiều sẽ xuất hiện gợi ý chặn, bạn có thể thực hiện thao tác chặn để ngăn họ tham gia đối chiến của bạn cho đến khi bỏ chặn."
  },
