  LanguageConfig_PermanentActivityRuleContent_CN = {
    Text = "<Title:Hành Lang Ký Ức>\n·Các hoạt động có đánh dấu \"Hành Lang Ký Ức\", sau khi thời gian hoạt động kết thúc sẽ được thu nạp vào \"Hành Lang Ký Ức\", có thể tiếp tục trải nghiệm lối chơi và cốt truyện tương ứng trong \"Hành Lang Ký Ức\".\n<Title:Quy tắc thu nạp>\n·Các hoạt động có đánh dấu \"Hành Lang Ký Ức\" sẽ có phần thưởng giới hạn thời gian phong phú, sau khi thời gian hoạt động kết thúc sẽ không thể nhận phần thưởng giới hạn thời gian nữa, xin các Người Giữ Bí Mật hãy nhận phần thưởng giới hạn thời gian kịp thời.\n·Sau khi hoạt động được thu nạp vào \"Hành Lang Ký Ức\", tiến độ trước đó sẽ được tự động giữ lại, các Người Giữ Bí Mật có thể tiếp tục trải nghiệm."
  },
