  LanguageConfig_RPGJJC_Desc_CN = {
    Text = "Bạn có thể tiêu thụ \"giấy phép diễn tập\"để thách đấu đội phòng thủ do các Người Giữ Gìn khác bố trí, nếu thách đấu thành công sẽ nâng cao thứ hạng. Bạn cũng cần phải cẩn thận bố trí đội phòng thủ của mình, nếu không có thể bị các Người Giữ Gìn khác thách đấu thành công và gây giảm thứ hạng. Thứ hạng càng cao, số \"huân chương diễn tập\" nhận được mỗi giờ càng nhiều. \"Giấy phép diễn tập\" sẽ tự động nhận được theo thời gian. \"Huân chương diễn tập\" có thể đổi lấy các đạo cụ như quyền vàng hồng, thuốc linh tri thức trong cửa hàng đổi thưởng."
