  },
  LanguageConfig_RailWayLevelAdjustmentTipsContent_CN = {
    Text = "Trong \"Tàu hỏa hạnh phúc lao nhanh\" có cơ chế đền bù cấp độ, quy tắc cụ thể như sau: \n · Trong đội điều tra, thân thể được đánh thức có cấp độ dưới 60 sẽ được đền bù lên 60 trong thử thách này. \n · Trong đội điều tra, thân thể được đánh thức có cấp độ kỹ năng dưới 5 sẽ được đền bù lên 5 trong thử thách này. \n · Trong đội điều tra, thân thể được đánh thức có \"Điềm báo điên loạn\" dưới 6 sẽ được đền bù lên 6 trong thử thách này. \n · Trong đội điều tra, thân thể được đánh thức có \"Khả năng thích ứng hình thái linh hồn\" dưới 5 sẽ được đền bù lên 5 trong thử thách này. \n · Nếu cấp độ Người Giữ Gìn dưới 60, sẽ được đền bù lên 60 trong thử thách này."
  },
  LanguageConfig_RailWayLevelAdjustmentTipsTitle_CN = {
    Text = "Đền bù cấp độ"
  },
  LanguageConfig_RailWayLevelAdjustmentTips_CN = {
    Text = "Đền bù cấp độ"
  },
  LanguageConfig_RailWayMaxProgress_CN = {
    Text = "Tiến độ cao nhất trong sự nghiệp"
  },
  LanguageConfig_RailWayOutBreakRecordTips_CN = {
    Text = "Tiến độ đỉnh mới!"
  },
  LanguageConfig_RailWayOutMaxExp_CN = {
    Text = "{s1}\"Điểm VIP\""
  },
  LanguageConfig_RailWayResonanceRuleContent_CN = {
    Text = "1, Tại \"Tàu hỏa hạnh phúc lao nhanh\" có sự tăng cường cảm ứng phong phú hơn, nhằm cung cấp sự hỗ trợ mạnh mẽ cho Người Giữ Gìn trong các thử thách. \n2, Trong \"Chụp ảnh trên đường\" có thể nhận được nguyên liệu nâng cấp cảm ứng, tiêu tốn nguyên liệu có thể kích hoạt hiệu ứng cảm ứng. \n3, Mỗi giai đoạn sẽ có sự kiện cảm ứng điều tra hành động, sau khi vào sự kiện cảm ứng điều tra hành động sẽ nhận được hiệu ứng cảm ứng mạnh mẽ tương ứng với chương, hiệu ứng cảm ứng này sẽ kéo dài đến khi toàn bộ cuộc điều tra kết thúc. \n4, Hiệu ứng cảm ứng nhận được trong \"Sự hỗ trợ của nhỏ\" N \"\" sẽ kéo dài từ khi bắt đầu điều tra đến khi điều tra kết thúc."
  },
  LanguageConfig_RailWayRulesContentV2_CN = {
    Text = "<Title:Giới thiệu gameplay>\n1、\"Tàu hỏa hạnh phúc lao nhanh\" là chế độ thử thách liên tiếp áp dụng quy tắc \"Bài sao\". Người giữ bí mật sẽ liên tiếp thử thách các trùm cuối đã xuất hiện trong nhiều điều tra hành động khác nhau trong những cuộc chạm trán ngẫu nhiên đầy biến đổi!\n2、Trong gameplay, giới hạn Di vật Trong Tay có thể được nâng lên tối đa 36 cái.\n3、Trong quá trình thử thách, có thể đồng thời sở hữu và tăng cường 3 loại hiệu ứng \"Cộng hưởng\" mạnh mẽ từ các điều tra hành động.\n4、Mỗi lần sử dụng Thân thể Linh tri thức khẩn cấp sẽ giảm 20% \"Điểm khách VIP\" nhận được trong lần thử thách này.\n5、Hỗ trợ thoát giữa chừng và Giữ lại tiến độ, nhưng Trạng thái đội ngũ sẽ không được cập nhật đồng bộ theo sự thay đổi bồi dưỡng bên ngoài. Tiến độ được Giữ lại tối đa đến 7 ngày sau lần thử thách trước, nếu trong thời gian Giữ lại không tiếp tục thử thách thì coi như từ bỏ thử thách, tiến độ sẽ không còn được Giữ lại.\n\n<Title:Bù cấp độ>\nTham gia \"Khởi hành chuyến tàu\" sẽ nhận được bù cấp độ, quy tắc cụ thể như sau:\n  ·Trong đội điều tra, Thể thức tỉnh có Cấp độ dưới 60 sẽ được bù lên Cấp độ 60 trong lần thử thách này.\n  ·Trong đội điều tra, Thể thức tỉnh có Cấp độ kỹ năng dưới 5 sẽ được bù lên Cấp độ 5 trong lần thử thách này.\n  ·Trong đội điều tra, Thể thức tỉnh có \"Điềm báo điên loạn\" dưới Cấp độ 6 sẽ được bù lên Cấp độ 6 trong lần thử thách này.\n  ·Trong đội điều tra, Thể thức tỉnh có \"Khả năng thích ứng hình thái linh hồn\" dưới Cấp độ 5 sẽ được bù lên Cấp độ 5 trong lần thử thách này.\n  ·Nếu Cấp độ người giữ bí mật dưới 60, trong lần thử thách này sẽ được bù lên Cấp độ 60.\n\n<Title:Giai đoạn Màn chơi>\n1、Một lần thử thách được chia thành ba giai đoạn, kẻ thù chủ đề và hiệu ứng cộng hưởng của mỗi giai đoạn sẽ được tạo ngẫu nhiên trong phạm vi tương ứng:\n  ·Giai đoạn một: Tương ứng nội dung chương một đến bốn của \"Bài Quên\".\n  ·Giai đoạn hai: Tương ứng nội dung chương năm đến tám của \"Bài Quên\".\n  ·Giai đoạn ba: Tương ứng nội dung chương một đến bốn của \"Bài sao\".\n ·Ở độ khó điên cuồng, sau khi hoàn thành thử thách giai đoạn ba sẽ thử thách thêm trùm cuối giai đoạn bốn là \"Tà Vy\".\n2、Sau khi đánh bại trùm giai đoạn, có thể chọn một trong 3 \"bàn lắc thời linh\" ngẫu nhiên để nhận.\n\n<Title:Độ khó và Di vật ban đầu>\nLần thử thách này có tổng cộng ba độ khó, mỗi độ khó có phần thưởng Màn chơi và Di vật ban đầu khác nhau, các người giữ bí mật có thể tìm hiểu thông tin chi tiết trước khi chọn độ khó thử thách.\n\n<Title:Phần thưởng Màn chơi>\n1、Bằng cách đánh bại Élite và trùm ở các độ khó có thể nhận được \"Điểm khách VIP\", \"Điểm khách VIP\" dùng để nâng Cấp độ \"Thông số phòng sang trọng\" để nhận phần thưởng.\n  ·Giai đoạn một: Đánh bại Élite/trùm nhận được \"Điểm khách VIP\" ×25/75\n  ·Giai đoạn hai: Đánh bại Élite/trùm nhận được \"Điểm khách VIP\" ×50/150\n  ·Giai đoạn ba: Đánh bại Élite/trùm nhận được \"Điểm khách VIP\" ×75/225\n2、Độ khó thử thách càng cao, sẽ nhận được càng nhiều \"Điểm khách VIP\".\n  ·[Độ khó khó khăn]: \"Điểm khách VIP\" nhận được khi hoàn thành ba giai đoạn tăng 150%\n\n  ·[Độ khó điên cuồng]: \"Điểm khách VIP\" nhận được khi hoàn thành ba giai đoạn tăng 400%\n ·Sau khi đánh bại trùm cuối \"Tà Vy\", có thể nhận thêm \"Điểm khách VIP\" × 1500.\n\n<Title:Cập nhật mùa giải>\n1、\"Danh Sách Quý Khách\" sẽ ghi lại những người giữ bí mật có thành tích thử thách xuất sắc, người giữ bí mật thử thách 1 lần trong mỗi mùa giải và thành công nhận được \"Điểm khách VIP\" sẽ được vào \"Danh Sách Quý Khách\".\n2、Xếp hạng mùa giải của \"Danh Sách Quý Khách\" dựa trên \"Điểm khách VIP\" nhiều nhất và \"số lượt\" ít nhất trong một lần thử thách, có thể thử thách lại để nâng cao xếp hạng.\n3、Sau khi mùa giải kết thúc, phần thưởng xếp hạng \"Danh Sách Quý Khách\" của mùa giải này sẽ được thanh toán qua thư.\n4、Mỗi mùa giải đều có Nhiệm Vụ Mùa Giải, hoàn thành Nhiệm Vụ Mùa Giải có thể nhận được phần thưởng phong phú. Nhiệm Vụ Mùa Giải sẽ được đặt lại mỗi lần cập nhật mùa giải.\n5、Khi chuyển mùa giải, Màn chơi đang trong chiến đấu sau khi hoàn thành thử thách có thể trực tiếp hoàn thành Nhiệm Vụ Mùa Giải mới nhất, nhưng không thể vào \"Danh Sách Quý Khách\"."
  },
  LanguageConfig_RailWayRulesContent_CN = {
    Text = "<Title:Giới thiệu gameplay>\n1、\"Tàu hỏa hạnh phúc lao nhanh\" là chế độ thách đấu liên tiếp áp dụng quy tắc \"Bài sao\". Người giữ bí mật sẽ liên tiếp thách đấu với các thủ lĩnh cuối cùng đã xuất hiện trong nhiều điều tra hành động giữa các cuộc chạm trán ngẫu nhiên biến đổi không ngừng!\n2、Trong gameplay, giới hạn Trong Tay Di vật tối đa có thể nâng lên 36 cái.\n3、Trong quá trình thách đấu có thể đồng thời sở hữu và tăng cường 3 loại hiệu ứng \"cộng hưởng\" mạnh mẽ trong điều tra hành động.\n4、Mỗi lần sử dụng 1 lần Thân thể Linh tri thức khẩn cấp, sẽ giảm 20% \"Điểm khách VIP\" nhận được trong lần thách đấu này.\n5、Hỗ trợ thoát giữa chừng và Giữ lại tiến độ, nhưng trạng thái đội ngũ sẽ không được cập nhật đồng bộ theo sự thay đổi nuôi dưỡng bên ngoài. Tiến độ được Giữ lại tối đa đến 7 ngày sau lần thách đấu trước, nếu trong thời gian Giữ lại không tiếp tục thách đấu thì coi như từ bỏ thách đấu, tiến độ sẽ không còn được Giữ lại.\n\n<Title:Bù cấp độ>\nTham gia \"Khởi hành tàu\" sẽ nhận được bù cấp độ, quy tắc cụ thể như sau:\n  ·Trong đội điều tra, Thể thức tỉnh chưa đủ cấp 60 sẽ được bù lên cấp 60 trong lần thách đấu này.\n  ·Trong đội điều tra, Thể thức tỉnh có cấp độ kỹ năng chưa đủ cấp 5 sẽ được bù lên cấp 5 trong lần thách đấu này.\n  ·Trong đội điều tra, Thể thức tỉnh có \"Điềm báo điên loạn\" chưa đủ cấp 6 sẽ được bù lên cấp 6 trong lần thách đấu này.\n  ·Trong đội điều tra, Thể thức tỉnh có \"Khả năng thích ứng hình thái linh hồn\" chưa đủ cấp 5 sẽ được bù lên cấp 5 trong lần thách đấu này.\n  ·Nếu cấp độ người giữ bí mật chưa đủ cấp 60, trong lần thách đấu này sẽ được bù lên cấp 60.\n\n<Title:Giai đoạn màn chơi>\n1、Một lần thách đấu tổng cộng được chia thành ba giai đoạn, kẻ thù chủ đề và hiệu ứng cộng hưởng của mỗi giai đoạn sẽ được tạo ngẫu nhiên trong phạm vi tương ứng:\n  ·Giai đoạn một: Tương ứng nội dung chương một đến bốn của \"Bài Quên\".\n  ·Giai đoạn hai: Tương ứng nội dung chương năm đến tám của \"Bài Quên\".\n  ·Giai đoạn ba: Tương ứng nội dung chương một đến bốn của \"Bài sao\".\n2、Sau khi đánh bại thủ lĩnh giai đoạn, có thể chọn một trong 3 \"bàn lắc thời linh\" ngẫu nhiên để nhận.\n\n<Title:Độ khó và Di vật ban đầu>\nLần thách đấu này có tổng cộng ba mức độ khó, mỗi mức độ khó có phần thưởng màn chơi và Di vật ban đầu khác nhau, các người giữ bí mật có thể tìm hiểu thông tin chi tiết trước khi chọn độ khó thách đấu.\n\n<Title:Phần thưởng màn chơi>\n1、Thông qua việc đánh bại Élite và thủ lĩnh ở các mức độ khó có thể nhận được \"Điểm khách VIP\", \"Điểm khách VIP\" dùng để nâng cấp độ \"Thông số phòng sang trọng\" để nhận phần thưởng.\n  ·Giai đoạn một: Đánh bại Élite/thủ lĩnh nhận \"Điểm khách VIP\" ×25/75 \n  ·Giai đoạn hai: Đánh bại Élite/thủ lĩnh nhận \"Điểm khách VIP\" ×50/150 \n  ·Giai đoạn ba: Đánh bại Élite/thủ lĩnh nhận \"Điểm khách VIP\" ×75/225 \n2、Độ khó thách đấu càng cao, sẽ nhận được càng nhiều \"Điểm khách VIP\".\n  ·[Độ khó khó khăn]: Hoàn thành ba giai đoạn, \"Điểm khách VIP\" nhận được tăng 150%\n  ·[Độ khó điên cuồng]: Hoàn thành ba giai đoạn, \"Điểm khách VIP\" nhận được tăng 400%\n\n<Title:Cập nhật mùa giải>\n1、\"Danh Sách Quý Khách\" sẽ ghi lại những người giữ bí mật có thành tích thách đấu xuất sắc, trong mỗi mùa giải thách đấu 1 lần và người giữ bí mật thành công nhận được \"Điểm khách VIP\" có thể vào \"Danh Sách Quý Khách\".\n2、Thứ hạng mùa giải của \"Danh Sách Quý Khách\" sẽ dựa trên \"Điểm khách VIP\" nhận được nhiều nhất trong một lần thách đấu và \"số vòng\" ít nhất đã sử dụng, có thể thách đấu lặp lại để nâng cao thứ hạng.\n3、Sau khi mùa giải kết thúc, phần thưởng xếp hạng \"Danh Sách Quý Khách\" của mùa giải này sẽ được tính toán qua thư.\n4、Mỗi mùa giải đều có Nhiệm Vụ Mùa Giải, hoàn thành Nhiệm Vụ Mùa Giải có thể nhận được phần thưởng phong phú. Nhiệm Vụ Mùa Giải sẽ được đặt lại mỗi khi mùa giải cập nhật.\n5、Khi chuyển đổi mùa giải, màn chơi đang trong trận đấu sau khi hoàn thành thách đấu có thể trực tiếp hoàn thành Nhiệm Vụ Mùa Giải mới nhất, nhưng không thể vào \"Danh Sách Quý Khách\" kỳ mới nhất."
  },
