  LanguageConfig_RailWayStageDifficultyBuffContent1_CN = {
    Text = "<Title:Phần thưởng màn chơi>\nGiai đoạn một: Đánh bại Élite/Lãnh đạo nhận được \"Điểm khách VIP\" ×25/75 \nGiai đoạn hai: Đánh bại Élite/Lãnh đạo nhận được \"Điểm khách VIP\" ×50/150 \nGiai đoạn ba: Đánh bại Élite/Lãnh đạo nhận được \"Điểm khách VIP\" ×75/225 \n<Title:Di vật ban đầu>\nNhận di vật \"Máy ảnh hoàn chỉnh của nhỏ\" N \"\" khi bắt đầu điều tra\n·<OrangeQuality:Cân bằng Điểm tính toán>:Hiệu quả tăng cường sức tính toán từ\"Cân bằng Điểm tính toán\" là tối đa 1 điểm, mỗi 1% Sự khuếch đại sát thương sẽ làm hiệu ứng Nghiên cứu độ sâu nhận thức tăng lên 1%.\n·<RedQuality:Cảm giác mệt mỏi khi đi đường dài>:Tất cả hiệu ứng hồi phục sinh lực trong trận đấu giảm 50%."
  },
  LanguageConfig_RailWayStageDifficultyBuffContent2_CN = {
    Text = "<Title:Phần thưởng màn chơi>\nĐộ khó của thử thách càng cao, sẽ nhận được càng nhiều \"Điểm khách VIP\". Hoàn thành ba giai đoạn nhận được \"Điểm khách VIP\" tăng 150%\n<Title:Di vật ban đầu>\nNhận di vật \"Máy ảnh cũ của nhỏ\" N \"\" khi bắt đầu điều tra\n·<OrangeQuality:Hòa vàng>: Hiệu ứng tăng cường sức tính toán từ\"Cân bằng Điểm tính toán\" tối đa là 1 điểm, mỗi 1% sự khuếch đại sát thương sẽ làm hiệu ứng nghiên cứu độ sâu nhận thức tăng 1%.\n·<OrangeQuality:Quà tặng chiều>: Khi bắt đầu khám phá, ngẫu nhiên nhận 1 di vật hình ảnh chiều, kích thước tay tối đa tăng 1.\n·<RedQuality:Cảm giác mệt mỏi khi đi đường dài>: Tất cả hiệu ứng hồi phục sinh lực trong trận đấu giảm 50%.\n·<RedQuality:Dấu hiệu choáng váng>: Khi bắt đầu trận đấu, tất cả thể thức tỉnh hiện tại giảm 50% điên cuồng và năng lượng chìa khóa bạc."
  },
  LanguageConfig_RailWayStageDifficultyBuffContent3V2_CN = {
    Text = "<Title:Thử thách đặc biệt>\nỞ độ khó Điên loạn, sau khi hoàn thành giai đoạn ba sẽ thêm thử thách Lãnh đạo cuối cùng giai đoạn bốn \"Tà Vy\".\n<Title:Phần thưởng màn chơi>\nĐộ khó thử thách càng cao, sẽ nhận được càng nhiều \"Điểm khách VIP\". \"Điểm khách VIP\" nhận được khi hoàn thành ba giai đoạn tăng 400%\nSau khi đánh bại Lãnh đạo cuối cùng \"Tà Vy\", có thể nhận thêm \"Điểm khách VIP\" × 1500.\n<Title:Di vật ban đầu>\nKhi bắt đầu điều tra nhận được Di vật \"Máy Ảnh Hỗn Loạn của \"N\"\"\n·<OrangeQuality:Điều Hòa Hoàng Kim>: Hiệu ứng tăng Điểm tính toán mang lại bởi \"Cân bằng Điểm tính toán\" tối đa là 1 điểm, mỗi 1% Khuếch đại sát thương sở hữu sẽ làm tăng hiệu ứng Nghiên cứu độ sâu nhận thức lên 1%.\n·<OrangeQuality:Quà Tặng Chiều Không Gian>: Khi bắt đầu khám phá, ngẫu nhiên nhận được 1 Di vật Hình ảnh chiều, Kích tước tay tối đa tăng 2.\n·<OrangeQuality:Lễ Được chúc phúc>: Phần thưởng đánh bại Lãnh đạo giai đoạn một, giai đoạn hai thay đổi thành chọn 1 trong 3 Di vật Được chúc phúc ngẫu nhiên.\n·<RedQuality:Cảm giác mệt mỏi khi đi đường dài>: Trong chiến đấu, tất cả hiệu ứng hồi Sinh lực giảm 50%.\n·<RedQuality:Dấu hiệu choáng váng>: Khi bắt đầu chiến đấu, Điên loạn hiện tại và Năng lượng chìa khóa bạc của tất cả Thể thức tỉnh giảm 50%.\n·<RedQuality:Hành lang đêm vĩnh cửu>: Khi bắt đầu khám phá, căn bản điên cuồng và giới hạn Năng lượng chìa khóa bạc của tất cả Thể thức tỉnh tăng 50%"
  },
  LanguageConfig_RailWayStageDifficultyBuffContent3_CN = {
    Text = "<Title:Phần thưởng màn chơi>\nĐộ khó của thử thách càng cao, sẽ nhận được càng nhiều \"Điểm khách VIP\". Hoàn thành ba giai đoạn nhận được \"Điểm khách VIP\" tăng 400%\n<Title:Di vật ban đầu>\nKhi bắt đầu điều tra nhận được di vật \"Máy ảnh hỗn loạn của nhỏ\" N \"\"\n·<OrangeQuality:Hòa hợp vàng>:Hiệu ứng tăng cường sức tính toán do \"Cân bằng Điểm tính toán\" mang lại tối đa là 1 điểm, mỗi 1% sự khuếch đại sát thương sẽ làm hiệu quả nghiên cứu độ sâu nhận thức tăng 1%.\n·<OrangeQuality:Quà tặng chiều>:Khi bắt đầu khám phá, ngẫu nhiên nhận 1 di vật hình ảnh chiều, kích thước tay tối đa tăng 2.\n·<OrangeQuality:Nghi thức được chúc phúc>:Phần thưởng lãnh đạo cho giai đoạn đầu tiên và thứ hai thay đổi thành di vật được chúc phúc ngẫu nhiên 3 chọn 1.\n·<RedQuality:Cảm giác mệt mỏi khi đi đường dài>:Trong chiến đấu, tất cả hiệu ứng hồi phục sinh lực giảm 50%.\n·<RedQuality:Dấu hiệu choáng váng>:Khi bắt đầu chiến đấu, tất cả thể thức tỉnh hiện tại điên cuồng và năng lượng chìa khóa bạc giảm 50%.\n·<RedQuality:Hành lang đêm vĩnh cửu>:Khi bắt đầu khám phá, tất cả thể thức tỉnh có cơ sở điên cuồng và năng lượng chìa khóa tối đa tăng 50%"
