  LanguageConfig_Resonance_Group_Desc_1_CN = {
    Text = "Tại nút [Quà tặng thiện ý], có thể thêm 1 lá [Quà đáp lại ngây thơ] vào bộ bài —— tiêu thụ 1 sức tính toán, trao 30 điên cuồng cho thân thể được đánh thức có số điên cuồng thấp nhất, tiêu thụ."
  },
  LanguageConfig_Resonance_Group_Desc_24_CN = {
    Text = "Trong sự kiện 「Đường Điên Rồ」, chỉ định một thân thể được đánh thức để gây ra rối loạn phân ly, mất bốn thẻ lệnh ban đầu, sau đó, con đường phía trước mới xuất hiện và mang lại cho bạn một vật tạo vàng 3 chọn 1. \nBạn có thể lần lượt lấy lại các thẻ lệnh đã mất trong bốn sự kiện 「Phân Mảnh Tinh Thần」 tiếp theo, các thẻ lệnh lấy lại sẽ trực tiếp sở hữu khắcăng độc đáo <EnsembleKeywords:「Hợp Tấu」>."
