  },
  LanguageConfig_Resonance_Group_Desc_3_CN = {
    Text = "Tại nút [khối u kỳ quái], có thể thêm một lá [Trái Tim Biến Dạng] vào bộ bài, tiêu thụ 0 sức tính toán. Sau khi đánh, bỏ tất cả các lá bài trên tay và rút số lá bài bằng số lá đã bỏ +1, tiêu thụ."
  },
  LanguageConfig_Resonance_Group_Desc_4_CN = {
    Text = "Tại nút [Rượu Mật Ong Ngọt], có thể thêm một lá [Rượu Mật Ong Ngọt] vào bộ bài —— tiêu tốn 1 đơn vị sức tính toán, nhận được 1 lớp rào cản tạm thời, tiêu thụ."
  },
  LanguageConfig_Resonance_Group_Desc_5_CN = {
    Text = "Tại các nút [Lễ Đại Hành] trong các màn chơi \"kẻ đắm chìm\" và sau đó, có thể nhận được hiệu ứng \"thần quốcchân tay\"—— sau mỗi lượt, gây 10% máu tối đa của đội nhóm cho kẻ địch hàng trước. \n Có thể thêm một thẻ bài \"phán quyết của Đại Hành Giả\" vào bộ bài —— không tốn sức tính toán, khi đánh ra sẽ mất 10% sức sống hiện tại, khiến \"thần quốcchân tay\" gây 3 lần thương cho kẻ địch hàng sau, nếu trong trận đấu với boss thì gây 10 lần thương. Tiêu thụ."
  },
  LanguageConfig_Resonance_Group_Desc_6_CN = {
    Text = "Tại \"Cánh Buồm Thuần Trắng\", thêm một \"Bức Màn Utopia\" vào bộ bài. Tiêu thụ 1 sức tính toán, xem 3 lệnh khóa khác với lệnh khóa đang mang theo, chọn ngay 1 lệnh để kích hoạt mà không cần chờ thời gian hồi. Trong trận chiến thủ lĩnh, có thể sử dụng thêm 1 lần nữa. Tiêu thụ."
  },
  LanguageConfig_Resonance_Group_Desc_7_CN = {
    Text = "Gần điểm khởi đầu khám phá, bạn sẽ gặp sự kiện cảm ứng đặc biệt - [Mẹ sinh thành], chọn một thẻ lệnh để làm cho nó nhận được khắc ấn đặc biệt [Mang thai], nhưng cũng khiến bạn nhận được 3 thẻ triệu chứng ngẫu nhiên. \n Khắc ấn [Mang thai]: khiến thẻ bài được giữ lại, khi kết thúc lượt nếu vẫn ở trong tay, nhận được một bản sao gốc có thêm giữ lại và tiêu thụ."
  },
  LanguageConfig_Resonance_Group_Desc_8_CN = {
    Text = "Khám phá gần điểm khởi đầu, bạn sẽ gặp sự kiện cảm ứng đặc biệt —— [Thẻ sinh viên Misaque], thêm [Ánh sáng yếu của đêm cực] vào bộ bài. \n [Ánh sáng yếu của đêm cực]: Chọn 1 thẻ lệnh từ bộ bài rút hoặc rác bài, thêm vào tay và giảm tiêu thụ sức tính toán xuống 0. Sử dụng 1 lần sau sẽ tiêu thụ."
  },
  LanguageConfig_Resonance_Group_Desc_9_CN = {
    Text = "Khám phá gần điểm xuất phát, bạn sẽ gặp sự kiện cảm ứng đặc biệt —— [Lễ nhập học], sẽ thêm[Ánh sáng yếu của đêm cực]vào bộ bài và nó sẽ kế thừa tất cả các buff từ chương thứ tám."
  },
  LanguageConfig_Resonance_Group_Desc_D05EX_CN = {
    Text = "Nhận tạo vật ban đầu \"Đoàn khảo sát\": Ban đầu sở hữu 30 thành viên đoàn khảo sát. Khi bắt đầu trận chiến, sẽ thêm 5 lá bài \"Nghi ngờ\" vào trong bộ bài. \"Nghi ngờ\": Khi đánh ra, sẽ lựa chọn tiêu hao số lượng thành viên khác nhau của đoàn khảo sát để nhận hiệu quả khác nhau. \nTrong quá trình khám phá, bạn sẽ liên tục đối mặt với các quyết định \"Nghi ngờ\" và tổn thất nhân sự của đoàn khảo sát. Khi kích hoạt trạm liên lạc, bạn sẽ có cơ hội nhận cứu viện. Cuối cùng, khi rút lui an toàn, bạn sẽ nhận \"Huân chương cứu nạn\" dựa trên số thành viên đoàn khảo sát còn lại, số người rút lui càng nhiều thì \"Huân chương cứu nạn\" càng mạnh."
  },
  LanguageConfig_Resonance_Group_Desc_Horla_CN = {
    Text = "Khám phá bắt đầu với sáng tạo ban đầu \"Bút và Mực của Ôrla\": sau khi chiến đấu kết thúc, nhận 1 lớp \"Mực Bút\", khi \"Mực Bút\"đạt 2 lớp, tiêu thụ nó để ngẫu nhiên đưa 1 lá \"Ý Tượng\" vào bộ bài. \nCó thể chọn \"Sáng Tác Thơ Dâng\" trong sự kiện cảm ứng đặc biệt [Quà Tặng Mùa Xuân]: chọn 3 lá \"Ý Tượng\", để Ôrla sáng tác \"Thơ Dâng\" cho bạn."
  },
  LanguageConfig_Resonance_Group_Desc_Lily_CN = {
    Text = "Tại sự kiện cộng hưởng \"Sự hoang mang của nhà sản xuất\", lựa chọn \"Nhờ đối tác giúp đỡ\" có thể nhận được 1 trong 3 đá khắc cao cấp."
  },
  LanguageConfig_Resonance_Group_Desc_MLYM_CN = {
    Text = "Khám phá bắt đầu bằng cách thêm 3 thẻ tăng cường vào bộ bài: <DerivativeCardKeywords_57:「gia đình ấm áp」>, <DerivativeCardKeywords_58:「bạn bè chân thành」>, <DerivativeCardKeywords_59:「cuộc sống ổn định」>.\n「gia đình ấm áp」: nhận 2 điểm sức tính toán.\n「bạn bè chân thành」: gây 1 lớp yếu đuối, tăng sát thương lên tất cả kẻ địch.\n「cuộc sống ổn định」: rút 2 lá bài."
