  LanguageConfig_Resonance_Group_Desc_x1_CN = {
    Text = "Tại sự kiện cảm ứng \"Chưa mất đi ý thức\", trộn một \"Bộ não dự phòng\" vào bộ bài. \"Bộ não dự phòng\" có thể tạm thời lưu trữ các thẻ bài đã sử dụng trước đây, và tùy theo từng trường hợp, quyết định có lấy ra và đặt vào tay hay không."
