  LanguageConfig_Resonance_Group_Desc_x2_CN = {
    Text = "Tại sự kiện \"Biến đổi cuộc sống\", chọn một người đánh thức biến đổi thành \"Côn trùng\".  \n\"Côn trùng\" có thời gian hồi phục Aliemus và nạp S-energy tăng 50%, tất cả thẻ lệnh tiêu hao số học -1, nhưng phát ra sẽ tiêu hao."
