  LanguageConfig_Resonance_Group_Desc_x3_CN = {
    Text = "Tại sự kiện \"Nghi thức trước tiệc\", đặt 1 \"Đặc chế lễ linh\" vào bộ bài.\n\"Đặc chế lễ linh\": tiêu hao Số học 1, tạm thời tăng 10% tỷ lệ chí mạng và sát thương chí mạng của tất cả Người đánh thức. Sau khi phát động \"Đặc chế lễ linh\", đặt 1 loại nguyên liệu vào trong đó, khiến nó có được hiệu ứng cụ thể vĩnh viễn trong trận chiến này!"
