  LanguageConfig_StorylineGuide_20_CN = {
    Text = "Văn bản tạm thời"
  },
  LanguageConfig_StorylineGuide_2_CN = {
    Text = "Nghệ sĩ, kẻ điên, người khổ hạnh, kẻ ngu ngốc… Thành phố này là bảo tàng của bạn, các bình tượng nến đứng ở nơi bắt đầu câu chuyện, khao khát sự hiện diện của bạn."
  },
  LanguageConfig_StorylineGuide_3_CN = {
    Text = "Gió tuyết của Rai ghét bỏ sự tàn sát, cô ấy đang chờ bạn, chỉ vì một giao dịch. Cô ấy sẽ mang đến cho bạn, bí mật mà bạn khao khát vô cùng. Giá của cô ấy mãi mãi tàn nhẫn, mãi mãi hợp lý."
