  LanguageConfig_StorylineGuide_4_CN = {
    Text = "Hãy nhớ lại, chiến đấu vì ký ức, chết vì ký ức. Ký ức là phúc âm của chúng ta, là bia mộ của chúng ta. Ngoài ký ức, chúng ta không có gì cả."
