  LanguageConfig_StorylineGuide_5_CN = {
    Text = "Trước khi những vì sao rơi xuống, chúng ta hướng về biển cầu nguyện: Mong rằng tiếng sóng yên bình bảo vệ chúng ta nhập vào giấc mơ, mong rằng chúng ta trở về trong vòng tay của quê hương, Giấc mơ dài không tỉnh dậy."
  },
  LanguageConfig_StorylineGuide_6_CN = {
    Text = "Hãy ngâm nga——vị vua cổ xưa, đã một lần nữa nhìn thấy ngai vàng của Ngài. Lời thánh chỉ sẽ mang đến vương quốc của Thần cho mỗi tín đồ tín tâm."
  },
  LanguageConfig_StorylineGuide_7_CN = {
    Text = "Lắng nghe, cầu nguyện, gọi, sinh sản, tuân theo lý tưởng cao quý nhất và dục vọng thấp hèn nhất. Nhân danh mẹ, Ngài có thể tồn tại trong hỗn mang và sợ hãi."
  },
  LanguageConfig_StorylineGuide_8_CN = {
    Text = "Ngọn đèn sáng mãi đã được thắp lên, ánh sáng u ám đó sẽ soi sáng con đường dẫn đến đích cuối cùng của bạn."
