  LanguageConfig_Task_Appoint_Rules_CN = {
    Text = "<Title:[Quy tắc phái đi]>\n·Người giữ bí mật có thể phái thân thể được đánh thức thực hiện nhiệm vụ điều tra hoặc nghiên cứu, sau khi hoàn thành nhiệm vụ có thể nhận được phần thưởng tương ứng.\n·Cần phải đạt tổng cấp độ phái đi đáp ứng yêu cầu nhiệm vụ mới có thể phái thành công, mỗi nhiệm vụ tối đa có thể phái 4 thân thể được đánh thức cùng lúc.\n·Mỗi 20 cấp độ vượt quá yêu cầu nhiệm vụ sẽ nhận được 1 phần thưởng bổ sung.\n·Mỗi thân thể được đánh thức chỉ có thể đảm nhận một nhiệm vụ phái đi cùng lúc. Nếu hủy phái giữa chừng, có thể nhanh chóng giải phóng thân thể được đánh thức đang bị chiếm dụng, nhưng sẽ không nhận được phần thưởng của nhiệm vụ đó.\n·Khi cấp độ điều tra của Người Giữ Gìn nâng lên 20/30/40/50/60, số lượng nhiệm vụ phái đi có thể đảm nhận sẽ tăng thêm 1.\n·Lưu ý: Hình thái bản nguyên của thân thể được đánh thức không thể phái đi."
  },
