  },
  LanguageConfig_TrinketAutoRefine_CN = {
    Text = "<Title:Tự động chuyển mã>\n·Tự động chuyển mã có thể thực hiện tối đa 100 lần chuyển mã dựa trên tình trạng vật liệu hiện tại.\n·Khi tự động chuyển mã, nếu trong kết quả chuyển mã có 1 thuộc tính chưa khóa có cường độ bằng 8, tự động chuyển mã sẽ dừng lại.\n·Khi vật liệu không đủ, tự động chuyển mã dừng lại.\n\n<Title:Bỏ qua>\n·Khi tự động chuyển mã sẽ hiển thị kết quả từng lần chuyển mã, có thể chọn bỏ qua quá trình chuyển mã. Sau khi bỏ qua, sẽ hiển thị trực tiếp kết quả cuối cùng của tự động chuyển mã."
  },
  LanguageConfig_TrinketAutoSelectTips_CN = {
    Text = "Tự động chọn: Ưu tiên chọn Giao ước có phẩm chất thấp hơn, Cấp độ thấp hơn làm vật liệu"
