  LanguageConfig_TrinketBindBonusDesc_CN = {
    Text = "Sau khi kết hợp, thuộc tính chính của Giao ước được tăng thêm {s1}!"
  },
  LanguageConfig_TrinketBindNoneSelectedTips_CN = {
    Text = "Không có Giao ước nào có thể kết hợp, vui lòng chọn ít nhất một cái."
  },
  LanguageConfig_TrinketBindRuleDesc_CN = {
    Text = "<Title:Kết Hợp Giao ước>\n·Người giữ bí mật hiện có thể Kết Hợp Giao ước cho Thể thức tỉnh.\n·Mỗi vị trí của Thể thức tỉnh có thể Kết Hợp 1 Giao ước, tổng cộng 6 cái.\n·Sau khi Kết Hợp, thuộc tính chính của Giao ước ở mỗi vị trí được tăng thêm 50%.\n·Giao ước đã Kết Hợp sẽ không xuất hiện trong \"Vật tư-Giao ước\" và \"Giả kim thuật\".\n·Trong biên đội và Trợ Chiến Thể thức tỉnh, nếu không trang bị Giao ước cho Thể thức tỉnh, Giao ước đã Kết Hợp sẽ được tự động trang bị.\n·tăng cường bộ phận Giao ước đã Kết Hợp không thay đổi Trạng thái Kết Hợp, mức tăng thuộc tính chính sẽ được cập nhật theo Trạng thái sau khi tăng cường.\n\n<Title:Phân Ly Giao ước>\n·Để chỉnh sửa hoặc hủy Kết Hợp Giao ước, cần Phân Ly Giao ước đã Kết Hợp trong trang Kết Hợp Giao ước.\n·Phân Ly từng bộ phận cần tiêu tốn 10 Giao ước cùng loại (không giới hạn vị trí).\n·Khi Phân Ly Giao ước, các Giao ước đã sử dụng sẽ không xuất hiện trong danh sách vật liệu."
  },
