  LanguageConfig_TrinketConversionReplace_CN = {Text = "Thay thế"},
  LanguageConfig_TrinketConversionRuleTitle_CN = {Text = "Quy tắc"},
  LanguageConfig_TrinketConversionRule_CN = {
    Text = "<Title:Chuyển ghi>\n·Chuyển ghi có thể thay đổi loại và giá trị của thuộc tính phụ mật khế, không ảnh hưởng đến loại và giá trị của thuộc tính chính.\n·Trong quá trình chuyển ghi, loại của thuộc tính phụ có thể trùng với thuộc tính chính, và các loại thuộc tính phụ cũng có thể trùng nhau.\n·Trong quá trình chuyển ghi, thuộc tính phụ sẽ nhận được giá trị với cường độ khác nhau.\n·Sau khi Người Giữ Gìn mở khóa chuyển ghi mật khế, bất kỳ mật khế nào mới nhận được bằng bất kỳ cách nào sẽ tự động được chuyển ghi miễn phí một lần.\n\n<Title:Khóa>\n·Trong quá trình chuyển ghi, nếu muốn giữ lại một số thuộc tính phụ, có thể nhấp vào nút khóa bên cạnh thuộc tính phụ để thực hiện khóa, loại và giá trị của thuộc tính phụ đã khóa sẽ được giữ lại trong quá trình chuyển ghi.\n·Tối đa có thể khóa đồng thời hai thuộc tính phụ.\n·Khóa 1 thuộc tính thì cần tiêu thụ thêm \"Bản còn lại mật khế\" × 20; khóa 2 thuộc tính thì cần tiêu thụ thêm \"Bút lông kỷ niệm\" × 10.\n·Khi chọn khóa 1 thuộc tính, có thể đánh dấu chọn \"Tiêu thụ bút lông kỷ niệm để bổ sung bản còn lại\"; nếu đánh dấu chọn, nếu \"Bản còn lại mật khế\" hiện tại không đủ, sẽ tự động tiêu thụ số lượng bút lông kỷ niệm tương ứng để thực hiện chuyển ghi."
  },
  LanguageConfig_TrinketConversion_CN = {Text = "Ghi âm"},
  LanguageConfig_TrinketCopyRules_CN = {
    Text = "1, Sau khi hoàn thành cấp độ trong Bản ghi cấm, có thể nhận được \"Giao ước\"!\n2, Các cấp độ được đề xuất với cấp độ khác nhau có thể nhận được số lượng \"Giao ước\" khác nhau.\n·Cấp độ được đề xuất 25 có thể nhận \"Giao ước\" × 1.\n·Cấp độ được đề xuất 35 có thể nhận \"Giao ước\" × 2.\n·Cấp độ được đề xuất 45 có thể nhận \"Giao ước\" × 3.\n3, Sau khi hoàn thành thử thách cấp độ, mở khóa tái hiện, tái hiện có thể ngay lập tức nhận thưởng nhiệm vụ của cấp độ đó. Mỗi lần tái hiện cần tiêu tốn \"Menophin\" tương đương với lượng cần thiết để điều tra.\n4, Mỗi khi hoàn thành một chương sự kiện điều tra sẽ mở khóa một cấp độ Giao ước.\n5, Nếu hoàn thành 3 sao cấp độ khó cao, tiến độ thử thách cấp độ khó thấp hơn sẽ tự động được đánh dấu là hoàn thành 3 sao."
