  LanguageConfig_WeeklyBossInstructions_CN = {
    Text = "\n<Title:Số lần thưởng>\n·Vào lúc 9 giờ sáng thứ Hai hàng tuần(GMT+8), số lần thưởng sẽ được đặt lại, sau khi hoàn thành bất kỳ cấp độ nào của \"Sự tồn tại siêu việt\" sẽ tiêu tốn 1 lần thưởng để nhận phần thưởng nhiệm vụ.\n·Số lần thưởng chưa sử dụng sẽ không được chuyển sang tuần tiếp theo.\n\n<Title:Tái hiện>\n·Sau khi hoàn thành lần đầu thách thức cấp độ\"Sự tồn tại siêu việt\", sẽ mở khóa tái hiện, tái hiện sẽ tiêu tốn 1 lần thưởng và nhận ngay phần thưởng nhiệm vụ.\n·Nếu hoàn thành ba sao ở cấp độ khó cao hơn, tiến độ thách thức ở độ khó thấp hơn sẽ tự động được đánh dấu là hoàn thành ba sao."
